using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
namespace OpenAntiLag {
 public sealed class MemoryPlayerStore:IPlayerStore {public PlayerPreferences Value=new PlayerPreferences();public PlayerPreferences Load(){return Value;}public void Save(PlayerPreferences value){PlayerStore.Validate(value);Value=value;}}
 public sealed class MemoryGameSessionStore:IGameSessionStore {public GameSessionMarker Value;public GameSessionMarker Load(){return Value;}public void Save(GameSessionMarker value){Value=value;}public void Clear(){Value=null;}}
 public sealed class PlayerContext:IDisposable {
  readonly IPlayerStore store;readonly GameDetectionService detection;readonly Engine engine;readonly ISystemClient system;readonly INvidiaStore nvidiaStore;readonly IAmdStore amdStore;readonly NvidiaController nvidia;readonly AmdProfiles amd;readonly NetworkClient network=new NetworkClient();readonly bool preview;
  public PlayerPreferences Preferences {get;private set;}public string Notice;public bool Initialized,LibraryReadOnly;public readonly OptimizationOrchestrator Optimizer;public readonly GameSessionController Session;public readonly SessionMeasurements Measurements=new SessionMeasurements();public readonly NetworkMonitor Network;public GameProcess[] Processes=new GameProcess[0];public event Action Changed;DateTime lastRecorded;bool refresh,disposed;
  public PlayerContext(Engine engine,ISystemClient system,Func<Task<bool>> acquire,Action release,bool preview,NetworkMonitor networkMonitor,NvidiaController nvidia,AmdProfiles amd,INvidiaStore nvidiaStore,IAmdStore amdStore,IPlayerStore store=null,IGameSessionStore sessionStore=null,GameDetectionService detection=null){this.engine=engine;this.system=system;this.preview=preview;Network=networkMonitor;this.nvidia=nvidia;this.amd=amd;this.nvidiaStore=nvidiaStore;this.amdStore=amdStore;this.store=store??(preview?(IPlayerStore)new MemoryPlayerStore():new PlayerStore());this.detection=detection??new GameDetectionService();try{Preferences=this.store.Load();}catch(Exception error){Preferences=new PlayerPreferences {SetupComplete=true};Notice=error.Message;LibraryReadOnly=true;}Optimizer=new OptimizationOrchestrator(new ExistingOptimizationBackend(engine,system),acquire,release);Session=new GameSessionController(Optimizer,sessionStore??(preview?(IGameSessionStore)new MemoryGameSessionStore():new GameSessionStore()));Optimizer.Changed+=delegate{var last=Optimizer.Operations().LastOrDefault();if(last!=null&&!Optimizer.Status.Busy&&last.Utc>lastRecorded){lastRecorded=last.Utc;if(!preview)Program.Log(last.Name+": "+last.Result);var game=Preferences.Games.FirstOrDefault(g=>g.Id==last.GameId);if(game!=null){game.LastResult=last.Result;Save();}}Emit();};Measurements.Changed+=Emit;Network.Sample+=sample=>Emit();}
  public bool Preview {get{return preview;}}public InstalledGame Selected {get{return Preferences.Games.FirstOrDefault(g=>g.Id==Preferences.SelectedGame);}}public PlayerProfile Profile {get{return Selected==null?Preferences.DefaultProfile:Selected.Profile;}}
  public bool Running {get{return Processes.Any(p=>GameSessionController.Matches(Selected,p));}}public int RunningPid {get{var p=Processes.FirstOrDefault(x=>GameSessionController.Matches(Selected,x));return p==null?0:p.Id;}}
  public void Emit(){if(disposed)return;var h=Changed;if(h!=null)h();}public bool Save(){if(LibraryReadOnly){Notice="Библиотека недоступна для записи. Автоматические действия отключены.";Emit();return false;}try{store.Save(Preferences);Emit();return true;}catch(Exception error){LibraryReadOnly=true;Notice="Настройки библиотеки не сохранены. Автоматическое применение в этом запуске отключено: "+error.Message;Emit();return false;}}
  public async Task Initialize(){if(Initialized)return;await Optimizer.Refresh();if(!preview)try{await Scan();}catch(Exception error){Notice="Поиск игр не завершён: "+error.Message;}Initialized=true;await Tick();Emit();}
  public async Task Scan(){var found=await Task.Run(()=>detection.Scan());foreach(var game in found)if(!Preferences.Games.Any(g=>g.Id==game.Id))Preferences.Games.Add(game);else{var saved=Preferences.Games.First(g=>g.Id==game.Id);saved.Name=game.Name;saved.Executable=game.Executable??saved.Executable;saved.InstallDirectory=game.InstallDirectory;saved.Artwork=game.Artwork;}if(Selected==null&&Preferences.Games.Count>0)Preferences.SelectedGame=Preferences.Games[0].Id;Notice="Найдено установленных игр: "+found.Count+". Данные прочитаны из локальных Steam-библиотек.";Save();}
  public void AddManual(string executable){var game=GameDetectionService.Manual(executable);if(!Preferences.Games.Any(g=>String.Equals(g.Executable,game.Executable,StringComparison.OrdinalIgnoreCase)))Preferences.Games.Add(game);Preferences.SelectedGame=Preferences.Games.First(g=>String.Equals(g.Executable,game.Executable,StringComparison.OrdinalIgnoreCase)).Id;Save();}
  public void Select(InstalledGame game){Preferences.SelectedGame=game.Id;Save();}
  public void SetProfile(PlayerProfile profile){if(Selected==null){Preferences.DefaultProfile=profile;Save();return;}if(Selected.Profile!=profile)Selected.Automatic=false;Selected.Profile=profile;if(profile==PlayerProfile.Custom)Selected.Automatic=false;Save();}
  public void SetAutomatic(bool value){var game=Selected;if(game==null||!game.CanWatch)throw new InvalidOperationException("Сначала укажите EXE выбранной игры");if(value&&game.Profile==PlayerProfile.Custom)throw new InvalidOperationException("Пользовательский профиль применяется только вручную");if(LibraryReadOnly)throw new InvalidOperationException("Библиотека не сохранена; автоматическое применение запрещено");bool previous=game.Automatic;game.Automatic=value;if(!Save()){game.Automatic=previous;Emit();}}
  public async Task Tick(){if(disposed||refresh||Optimizer.Status.Busy)return;refresh=true;try{if(!preview)Processes=await Task.Run(()=>GameConnections.Processes());if(disposed)return;var selected=Selected;if(LibraryReadOnly&&selected!=null)selected=new InstalledGame {Id=selected.Id,Name=selected.Name,Executable=selected.Executable,InstallDirectory=selected.InstallDirectory,Profile=selected.Profile,Automatic=false};await Session.Tick(selected,Processes);if(Preferences.LocalMonitoring)await Measurements.Configure(true,RunningPid);else await Measurements.Configure(false,0);await Optimizer.Refresh();if(!Optimizer.Status.HasProfile&&Selected!=null&&Selected.Automatic&&!Running){Optimizer.Status.Stage=OptimizationStage.WaitingForGame;Optimizer.Status.Message=Session.Message??"Ожидание запуска игры";}}catch(Exception error){Notice=error.Message;}finally{refresh=false;Emit();}}
  public async Task SetMonitoring(bool enabled){Preferences.LocalMonitoring=enabled;await Measurements.Configure(enabled,RunningPid);Save();}
  public string GpuStatus(){try{var n=nvidiaStore.Load();var a=amdStore.Load();if(n!=null||a!=null)return (n!=null?(n.Phase=="Applied"?"Есть подтверждённый при применении профиль NVIDIA":"Нужно восстановить настройки NVIDIA"):"")+(a!=null?(a.Phase=="Applied"?" Есть подтверждённый при применении профиль AMD":" Нужно восстановить настройки AMD"):"");return "Нет активных изменений видеокарты от приложения";}catch{return "Нужно проверить восстановление видеокарты";}}
  public int NetworkPendingQos(){try{return network.State.Qos.Count;}catch{return -1;}}
  public async Task ApplyBackgroundLimit(string path,long bits){if(preview)throw new InvalidOperationException("Предпросмотр: запись сети отключена");path=Path.GetFullPath(path);if(!File.Exists(path)||GameConnections.IsProtected(path))throw new ArgumentException("Выберите обычную пользовательскую программу. Системные программы и античит защищены.");if(Session.Faceit)throw new InvalidOperationException("При обнаруженном FACEIT применяйте дополнительные ограничения только после проверки совместимости в расширенных настройках.");var p=new QosPolicy {Name="OpenAntiLag-"+Guid.NewGuid().ToString("N"),Path=path,BitsPerSecond=bits};NetworkValidation.Qos(p);await Optimizer.Module("Ограничение фоновой отправки",()=>{network.Run("qos",new NetworkRequest {Qos=p});return "Ограничение отправки сохранено и проверено Windows. Фактическое действие зависит от ОС.";},()=>network.State.Qos.Any(q=>q.Applied.Name==p.Name));}
  public string NetworkStatus(){try{var s=network.State;return s.Qos.Count>0?"Есть сохранённые ограничения: "+s.Qos.Count+". Проверка и восстановление — в подробностях.":"Ограничения не применены";}catch{return "Нужно проверить сетевой журнал";}}
  public async Task ApplyGpu(bool useAmd,string profile,int fps){if(preview)throw new InvalidOperationException("Запись GPU недоступна в предпросмотре");if(Session.Faceit)throw new InvalidOperationException("Обнаружен FACEIT. В простом режиме глобальные изменения GPU отключены; совместимость не подтверждена.");if(profile=="Стандартный"){await Optimizer.Module("Видеокарта",()=>useAmd?amd.Restore():nvidia.Restore(),()=>useAmd?amdStore.Load()==null:nvidiaStore.Load()==null);return;}if(useAmd){string id=await Task.Run(()=>amd.Devices().Select(g=>g.Id).FirstOrDefault());if(id==null)throw new InvalidOperationException("Совместимая Radeon не обнаружена");await Optimizer.Module("AMD",()=>amd.Apply(id,true,profile=="Максимальная плавность"),()=>{var state=amdStore.Load();return state!=null&&state.Phase=="Applied";});}else await Optimizer.Module("NVIDIA",()=>nvidia.Apply(NvidiaPreset.Build(profile=="Максимальная плавность",fps,false,false)),()=>{var state=nvidiaStore.Load();return state!=null&&state.Phase=="Applied";});Emit();}
  public RecoveryModule[] Recovery(){return new[]{new RecoveryModule {Name="Профиль Windows",Pending=()=>{var s=Optimizer.Read();return s.UserPhase!="Disabled"||s.MachinePhase!="Disabled";},Restore=()=>{new ProfileController(engine,system).Disable();return "Профиль Windows восстановлен. Если требовались системные изменения, перезагрузите ПК.";}},new RecoveryModule {Name="NVIDIA",Pending=()=>nvidiaStore.Load()!=null,Restore=()=>nvidia.Restore()},new RecoveryModule {Name="AMD",Pending=()=>amdStore.Load()!=null,Restore=()=>amd.Restore()},new RecoveryModule {Name="Ограничения интернета",Pending=()=>network.State.Qos.Count>0,Restore=()=>{network.Run("restore-qos",new NetworkRequest());return "Политики приложения восстановлены";}},new RecoveryModule {Name="DNS Windows",Pending=()=>network.State.Dns.Count>0,Restore=()=>{network.Run("restore-dns",new NetworkRequest());return "Сохранённый DNS восстановлен";}}};}
  public void Dispose(){disposed=true;Measurements.Dispose();}
 }
}
